import { describe, it, expect } from "bun:test";

import { Mulberry32Engine } from "../engine/Mulberry32Engine";
import { MersenneTwisterEngine } from "../engine/MersenneTwisterEngine";
import { XORShift128PlusEngine } from "../engine/XORShift128PlusEngine";
import { Xoshiro256Engine } from "../engine/Xoshiro256Engine";

// Known-answer tests: each engine must reproduce the raw output of its
// canonical C reference implementation, not just be self-consistent.
// Expected values were generated by compiling the reference sources:
//   - mulberry32: Tommy Ettinger's mulberry32
//   - xorshift128+: Vigna 2014 (original 23/17/26 shifts, as used in V8),
//     seeded as [seed, seed ^ 0x9e3779b97f4a7c15]
//   - xoshiro256**: Blackman & Vigna, state seeded by 4 SplitMix64 outputs
//   - MT19937: Matsumoto & Nishimura mt19937ar.c (init_genrand + genrand_int32)
// See GitHub issue #1 for the MT seeding bug these tests would have caught.

const SEEDS = [0, 42, 123456789] as const;
type Seed = (typeof SEEDS)[number];

// 32-bit engines return uint32 / 2^32, so the raw output is recovered exactly.
const toUint32 = (x: number) => x * 2 ** 32;
// 64-bit engines return Number(uint64) / 2^64; compute the expected float the same way.
const fromUint64 = (x: bigint) => Number(x) / 2 ** 64;

const draw = (engine: { next(): number }, n: number) =>
  Array.from({ length: n }, () => engine.next());

describe("reference vectors", () => {
  describe("Mulberry32", () => {
    const expected: Record<Seed, number[]> = {
      0: [1144304738, 1416247, 958946056, 627933444, 2007157716],
      42: [2581720956, 1925393290, 3661312704, 2876485805, 750819978],
      123456789: [1107202814, 4169434471, 3372958138, 885470128, 1301683845],
    };
    for (const seed of SEEDS) {
      it(`seed ${seed} matches reference outputs`, () => {
        const engine = new Mulberry32Engine(seed);
        expect(draw(engine, 5).map(toUint32)).toEqual(expected[seed]);
      });
    }
  });

  describe("XORShift128Plus", () => {
    const expected: Record<Seed, { outputs: bigint[]; state: string[] }> = {
      0: {
        outputs: [
          4354685450906930783n,
          8860548701691037008n,
          7687965586592171813n,
          18045265895882104760n,
          14684897714389753756n,
        ],
        state: ["7817134305687686041", "6867763408702067715"],
      },
      42: {
        outputs: [
          4354685450722383113n,
          8860548701506489331n,
          7690639599055644505n,
          18046391795975869580n,
          14680676483104456452n,
        ],
        state: ["7815586193317978204", "6865090289786478248"],
      },
      123456789: {
        outputs: [
          4353940921364579750n,
          8859804172247784555n,
          6565112915489176269n,
          2174872198327337716n,
          3895973734738545692n,
        ],
        state: ["11516337352923402220", "10826380455524695088"],
      },
    };
    for (const seed of SEEDS) {
      it(`seed ${seed} matches reference outputs and state`, () => {
        const engine = new XORShift128PlusEngine(seed);
        expect(draw(engine, 5)).toEqual(expected[seed].outputs.map(fromUint64));
        // The state holds the full 64-bit words, so this check is bit-exact.
        expect(engine.getState()).toBe(JSON.stringify(expected[seed].state));
      });
    }
  });

  describe("Xoshiro256", () => {
    const expected: Record<Seed, { outputs: bigint[]; state: string[] }> = {
      0: {
        outputs: [
          11091344671253066420n,
          13793997310169335082n,
          1900383378846508768n,
          7684712102626143532n,
          13521403990117723737n,
        ],
        state: [
          "7836616895581041836",
          "18289817841045631201",
          "14378738937188272626",
          "10876364233727353416",
        ],
      },
      42: {
        outputs: [
          1546998764402558742n,
          6990951692964543102n,
          12544586762248559009n,
          17057574109182124193n,
          18295552978065317476n,
        ],
        state: [
          "9097251175449367461",
          "14529276094648713868",
          "14088181525258040340",
          "14940061133522366373",
        ],
      },
      123456789: {
        outputs: [
          15127205273500847298n,
          16265768176396019016n,
          1514321867679316104n,
          9853693475100939714n,
          16001046604883718113n,
        ],
        state: [
          "7220952973751088760",
          "17919872239178026000",
          "17717548042181000454",
          "14061371703894613376",
        ],
      },
    };
    for (const seed of SEEDS) {
      it(`seed ${seed} matches reference outputs and state`, () => {
        const engine = new Xoshiro256Engine(seed);
        expect(draw(engine, 5)).toEqual(expected[seed].outputs.map(fromUint64));
        expect(engine.getState()).toBe(JSON.stringify(expected[seed].state));
      });
    }
  });

  describe("MersenneTwister", () => {
    const expected: Record<Seed | 1 | 5489, number[]> = {
      0: [2357136044, 2546248239, 3071714933, 3626093760, 2588848963],
      1: [1791095845, 4282876139, 3093770124],
      42: [1608637542, 3421126067, 4083286876, 787846414, 3143890026],
      5489: [3499211612, 581869302, 3890346734],
      123456789: [2288500408, 4254805660, 2294099250, 56498137, 2188513626],
    };
    for (const [seedStr, outputs] of Object.entries(expected)) {
      const seed = Number(seedStr);
      it(`seed ${seed} matches reference outputs`, () => {
        const engine = new MersenneTwisterEngine(seed);
        expect(draw(engine, outputs.length).map(toUint32)).toEqual(outputs);
      });
    }
  });
});
